<script>
  import { browser } from '$app/environment';
  import { onDestroy, onMount } from 'svelte';

  export let selected = 0;
  export let selectionColor = 'var(--primary-color)';
  const DICT = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const KEYS = ['user_id', 'email', 'name'];
  const DEFAULT_DATA = {
    user_id: '111111-11111111-11111111-111111',
    email: 'anon_user_1111@id.pportal.io',
    name: 'Anonymous'
  };
  let element;
  let intersectionObserver;
  let displayed = false;
  let data = { ...DEFAULT_DATA };
  $: updateItem(KEYS[selected], displayed);

  function sleep() {
    return new Promise((resolve) => setTimeout(resolve, 20));
  }

  function randomSubstring(length = 1, suffix = 'X') {
    let result = suffix;
    while (result.length < length) {
      result = DICT[Math.floor(Math.random() * DICT.length)] + result;
    }
    return result;
  }

  async function updateItem(key, displayed) {
    if (!displayed) return;
    const scrambledStrLength = 30;
    const length = DEFAULT_DATA[key].length;
    for (let i = 0; i < length + scrambledStrLength + 1; i++) {
      const randomStr = randomSubstring(Math.min(i, scrambledStrLength, length, i > length ? scrambledStrLength + length - i : i), i > 0 && i < length - scrambledStrLength ? 'X' : '');
      data[key] = DEFAULT_DATA[key].substring(0, Math.min(i, length) - randomStr.length) + randomStr + (i < length ? DEFAULT_DATA[key].substring(i) : '');
      await sleep();
    }
  }

  function observerCallback(entries) {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        displayed = true;
        intersectionObserver.disconnect();
        intersectionObserver = undefined;
      }
    });
  }

  onMount(async () => {
    if (browser) {
      intersectionObserver = new IntersectionObserver(observerCallback, {
        root: null,
        rootMargin: '0px',
        threshold: 0.8
      });
      intersectionObserver.observe(element);
    }
  });

  onDestroy(() => {
    if (intersectionObserver) {
      intersectionObserver.disconnect();
      intersectionObserver = undefined;
    }
  });
</script>

